import{a as e,n as t,o as n,r,s as i,t as a}from"./app-CFD1XTs1.js";import{t as o}from"./plugin-vue_export-helper-BDNMzG2s.js";var s=JSON.parse(`{"path":"/web3/tools/coq.html","title":"FV","lang":"zh-CN","frontmatter":{"description":"FV 形式化验证（Formal Verification）是一种通过数学方法对程序的正确性进行证明的技术。它不依赖于测试样例，而是通过形式化规范（Specification）和自动/交互式工具，验证程序是否在所有可能执行路径下都满足这些规范。 语言工具 Coq coqc wallet.v","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"FV\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/tools/coq.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"FV"}],["meta",{"property":"og:description","content":"FV 形式化验证（Formal Verification）是一种通过数学方法对程序的正确性进行证明的技术。它不依赖于测试样例，而是通过形式化规范（Specification）和自动/交互式工具，验证程序是否在所有可能执行路径下都满足这些规范。 语言工具 Coq coqc wallet.v"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1750471400000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.31,"words":394},"filePathRelative":"web3/tools/coq.md","autoDesc":true}`),c={name:`coq.md`};function l(o,s,c,l,u,d){let f=i(`DocsAD`);return n(),t(`div`,null,[s[0]||=a(`h1`,{id:`fv`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#fv`},[a(`span`,null,`FV`)])],-1),s[1]||=a(`p`,null,`形式化验证（Formal Verification）是一种通过数学方法对程序的正确性进行证明的技术。它不依赖于测试样例，而是通过形式化规范（Specification）和自动/交互式工具，验证程序是否在所有可能执行路径下都满足这些规范。`,-1),e(f),s[2]||=r(`<h2 id="语言工具" tabindex="-1"><a class="header-anchor" href="#语言工具"><span>语言工具</span></a></h2><table><thead><tr><th>工具 / 语言</th><th>适用平台</th><th>说明</th></tr></thead><tbody><tr><td><strong>Coq</strong></td><td>多领域，支持建模</td><td>交互式定理证明器，基于高阶逻辑</td></tr><tr><td><strong>Isabelle/HOL</strong></td><td>多领域</td><td>功能类似 Coq，更偏重自动化推理</td></tr><tr><td><strong>Certora Prover</strong></td><td>Solidity</td><td>商用级规则式验证，语法接近自然语言</td></tr><tr><td><strong>KEVM</strong></td><td>Ethereum / EVM</td><td>EVM 的形式化语义实现</td></tr><tr><td><strong>Move Prover</strong></td><td>Move（Aptos / Sui）</td><td>用于 Move 合约的自动验证</td></tr><tr><td><strong>F*</strong></td><td>多用途安全验证语言</td><td>微软开发，适合高安全场景</td></tr><tr><td><strong>Michelson + Mi-Cho-Coq</strong></td><td>Tezos</td><td>支持形式化验证 Michelson 合约</td></tr></tbody></table><h2 id="coq" tabindex="-1"><a class="header-anchor" href="#coq"><span>Coq</span></a></h2><ul><li>coqc wallet.v</li></ul><div class="language-coqc line-numbers-mode" data-highlighter="shiki" data-ext="coqc" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-coqc"><span class="line"><span>(* Wallet.v *)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(* 导入自然数库 *)</span></span>
<span class="line"><span>Require Import Nat.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(* 定义钱包的状态：仅用一个余额来表示 *)</span></span>
<span class="line"><span>Record Wallet := {</span></span>
<span class="line"><span>  balance : nat (* Coq 中的 nat 是非负整数 *)</span></span>
<span class="line"><span>}.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(* 定义转账函数，尝试从钱包中扣除 n 元 *)</span></span>
<span class="line"><span>Definition withdraw (w : Wallet) (n : nat) : option Wallet :=</span></span>
<span class="line"><span>  if leb n (balance w) then</span></span>
<span class="line"><span>    Some {| balance := (balance w) - n |}</span></span>
<span class="line"><span>  else</span></span>
<span class="line"><span>    None.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(* 定理：如果成功扣款，余额永远不为负（在 Coq 中一定成立） *)</span></span>
<span class="line"><span>Theorem withdraw_preserves_nonnegative :</span></span>
<span class="line"><span>  forall (w : Wallet) (n : nat) (w&#39;: Wallet),</span></span>
<span class="line"><span>    withdraw w n = Some w&#39; -&gt;</span></span>
<span class="line"><span>    exists b, balance w&#39; = b.</span></span>
<span class="line"><span>Proof.</span></span>
<span class="line"><span>  intros w n w&#39; H.</span></span>
<span class="line"><span>  unfold withdraw in H.</span></span>
<span class="line"><span>  destruct (leb n (balance w)) eqn:Hle.</span></span>
<span class="line"><span>  - (* 成功取款 *)</span></span>
<span class="line"><span>    inversion H. subst.</span></span>
<span class="line"><span>    exists (balance w - n). reflexivity.</span></span>
<span class="line"><span>  - (* 不可能，因为返回值是 Some，但我们构造的是 None *)</span></span>
<span class="line"><span>    discriminate H.</span></span>
<span class="line"><span>Qed.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,5)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};